import type { Question } from "@/lib/types";

// Hard exam pool — Domain II. Original items; reserved primarily for mock exam clusters.
function o(label: string, text: string, isCorrect = false, sort = 0) {
  return { label, text, isCorrect, sort };
}

const raw: Array<{
  id: string; c: string; type: Question["type"]; d: 1 | 2 | 3; stem: string;
  opts: [string, boolean][]; why: string; wrong?: Record<string, string>;
  strat?: string; trap?: Question["trapType"]; bok: string; multi?: boolean;
}> = [
  // ───────── II.A — privacy law applied to AI (7) ─────────
  { id: "e-ii-1", c: "ii-a", type: "best", d: 3, stem: "Velora Assur, an EU insurer, auto-adjudicates travel-insurance claims with a model whose denials carry significant financial effect. To stay outside GDPR Article 22, it routes every denial to a claims clerk who sees only a one-line score, has no access to the underlying file, no authority to overturn, and clears roughly 400 denials per shift. A rejected claimant invokes her Article 22 rights; Velora replies that the decision was not solely automated. The strongest analysis is:", opts: [["Article 22 still applies — review by a human who lacks the authority, competence and information to change the outcome is a rubber stamp, not meaningful involvement", true], ["Article 22 is excluded because a human formally actions each denial before it is issued", false], ["Article 22 is excluded because travel-claim denials are routine commercial decisions without legal or similarly significant effect", false], ["Article 22 applies, but Velora can cure it by relying on the implied consent claimants give at policy renewal", false]], why: "Meaningful human involvement requires the authority and competence to weigh all relevant data and actually change the decision. A clerk clearing 400 denials a shift with no file access and no override power adds no human judgement, so the decision remains solely automated and the Article 22 safeguards (human intervention, express view, contest) attach.", wrong: { B: "The formalism bait: a scripted human touchpoint is not meaningful involvement — the clerk cannot deviate, so the click changes nothing.", C: "The stem states the denials carry significant financial effect; refusing an insurance payout is squarely significant-effect territory.", D: "The consent exception demands EXPLICIT consent to the automated decision-making; implied renewal consent cannot ground it." }, strat: "When a stem engineers a human into the loop, test that human's authority, information and real influence. A click-through reviewer never defeats 'solely automated'.", trap: "synonym-bait", bok: "Domain II, Competency A" },
  { id: "e-ii-2", c: "ii-a", type: "role", d: 3, stem: "Quenby Analytics licenses its hosted text-generation API to EU freight firm Castellan, which submits shipment-dispute emails as prompts. The contract labels Quenby a processor acting only to return outputs — but Quenby also retains every customer's prompts to fine-tune its next model for its whole client base. Castellan's DPO asks how the GDPR roles actually fall. The best allocation is:", opts: [["Quenby is a processor when generating outputs on Castellan's instructions, but an independent controller for the retention and fine-tuning it performs for its own purposes", true], ["Quenby is a processor for all the processing, because that is what the contract designates", false], ["Castellan is the controller of the fine-tuning, because the prompts originated in its systems", false], ["The parties are joint controllers for everything, because both benefit from an improved model", false]], why: "GDPR roles follow who determines the purposes and means of processing, not contract labels. Serving outputs under instruction is processor work; deciding to reuse customer prompts to improve Quenby's own product is Quenby setting its own purpose — controller status for that processing.", wrong: { B: "Labels do not control the analysis; a 'processor' that processes for its own purposes is a controller for those purposes regardless of the contract.", C: "Where data originated is irrelevant to role allocation — Castellan neither decided on nor directs the fine-tuning purpose.", D: "Joint controllership requires jointly determined purposes and means; incidental benefit from a better model does not create it." }, strat: "Generative-AI vendor items turn on purpose-splitting: same vendor, two capacities. Ask per processing operation: whose purpose is being served?", trap: "true-but-irrelevant", bok: "Domain II, Competency A" },
  { id: "e-ii-3", c: "ii-a", type: "distinction", d: 3, stem: "Rentivo, an EU car-sharing platform, instantly and fully automatically rejects some applicants on a damage-risk score, with significant effect. Legal proposes three routes to legitimise this under Article 22: (1) the consent users give by ticking the general terms-of-service box; (2) arguing the automated check is necessary to enter the rental contract at the moment of instant booking; (3) a legitimate-interests balancing test. Which proposals can actually ground an Article 22 exception?", opts: [["Only (2) — contractual necessity is an Article 22 exception; a bundled terms-of-service tick is not the explicit consent the exception demands, and legitimate interests is not an Article 22 exception at all", true], ["(1) and (2) — any valid GDPR consent works alongside contractual necessity", false], ["(1), (2) and (3) — each is a lawful basis under Article 6, so each unlocks Article 22", false], ["Only (3) — legitimate interests is the default basis for commercial risk scoring", false]], why: "Article 22's exceptions are exactly three: necessity for a contract, authorization by law, and EXPLICIT consent. A terms-of-service checkbox is ordinary bundled consent, not explicit consent to automated decision-making; legitimate interests appears in Article 6 but is absent from Article 22's list.", wrong: { B: "Synonym bait: 'consent' and 'explicit consent' are not interchangeable — Article 22 demands the heightened form.", C: "True of Article 6, irrelevant to Article 22: the lawful-basis menu is wider than the narrow exception list for solely automated significant decisions.", D: "Legitimate interests never authorizes solely automated decisions with significant effects, whatever its role elsewhere in the GDPR." }, strat: "Keep two lists in your head: Article 6 lawful bases (six) versus Article 22 exceptions (three). IAPP loves options that quietly swap one list for the other.", trap: "synonym-bait", bok: "Domain II, Competency A" },
  { id: "e-ii-4", c: "ii-a", type: "best", d: 3, stem: "A data-governance lead at EU telehealth firm Mondara is assembling training data for a symptom-triage model. The privacy officer instructs the team to cut every field that is not strictly indispensable, regardless of what that does to triage accuracy, citing data minimization. What does the GDPR principle actually require?", opts: [["Limit the data to what is adequate, relevant and necessary for the triage purpose — a field-by-field assessment that weighs each input's clinical contribution, not an accuracy-blind cut", true], ["Proceed with the accuracy-blind cut — minimization always overrides model performance", false], ["Keep all fields but encrypt them, since strong security measures satisfy minimization", false], ["Defer minimization until post-market monitoring reveals which fields mattered", false]], why: "Minimization is purpose-relative: data must be adequate, relevant and limited to what is necessary for the stated purpose. A field that materially improves clinically safe triage can be necessary; stripping it blind to effectiveness serves neither patients nor the principle. The exam-tested formulation is minimization BALANCED with utility.", wrong: { B: "The planted absolute — 'regardless' of effectiveness is precisely the wording IAPP marks wrong; the principle demands a balance, not a blind cut.", C: "Security and minimization are different principles; encrypting excess data does not make collecting it necessary.", D: "Minimization is a by-design obligation at collection, not a post-deployment cleanup exercise." }, strat: "When an option maximizes one principle 'regardless' of everything else, it is bait. Governance answers balance competing goods.", trap: "absolute", bok: "Domain II, Competency A" },
  { id: "e-ii-5", c: "ii-a", type: "best", d: 3, stem: "EU logistics operator Farstrand wants to replace warehouse badge entry with fingerprint-verification terminals, storing templates as mathematical hashes rather than images. HR proposes collecting employee consent through the onboarding pack. Privacy counsel's correct starting point under the GDPR is:", opts: [["Fingerprint templates used to uniquely identify workers are special-category biometric data, so Farstrand needs an Article 9 condition plus heightened safeguards — and employee consent is a fragile basis given the employment power imbalance", true], ["The fingerprints are ordinary personal data because they are collected for security rather than marketing", false], ["Onboarding-pack consent resolves the issue, since consent legitimises any biometric processing", false], ["The GDPR does not apply because the templates are stored as hashes, not fingerprint images", false]], why: "Biometric data processed to uniquely identify a person is a special category attracting heightened requirements: a lawful basis plus an Article 9 condition and stronger safeguards. In employment, consent is presumptively not freely given because of the power imbalance, so counsel should not build the deployment on it.", wrong: { B: "The purpose of collection does not demote the data category — identification-grade biometrics are special-category whatever the motive.", C: "'Any' overreaches twice: consent must be freely given, which employment undermines, and special-category processing needs more than a signature in an onboarding pack.", D: "The too-narrow technical dodge: a hashed template still relates to an identifiable person and still functions as biometric data." }, strat: "Form-of-storage arguments (hashes, embeddings, templates) rarely remove data from GDPR scope. Classify by function — does it uniquely identify? — not by format.", trap: "too-narrow", bok: "Domain II, Competency A" },
  { id: "e-ii-6", c: "ii-a", type: "best", d: 3, stem: "The EU subsidiary of US retailer Harwick & Lane is told to stream its European employees' HR records into the parent's new AI workforce-planning platform hosted in Virginia, with ingestion starting next sprint. The subsidiary's privacy lead should FIRST:", opts: [["Resolve the cross-border transfer position — identify and validate a lawful transfer mechanism — before any employee data leaves the EU", true], ["Begin ingestion on schedule and negotiate transfer clauses in parallel so the sprint is not blocked", false], ["Anonymize the records after transfer so that the US processing falls outside the GDPR", false], ["Rely on the parent company's US privacy policy as the governing safeguard", false]], why: "Cross-border transfer rules are a precondition: the lawful mechanism must exist and be assessed before the data moves. Reviewing data-transfer law before any processing is the pattern the exam rewards — transfers are not a task to regularise after the fact.", wrong: { B: "Wrong economics: sprint pressure never converts an unlawful transfer into a parallel workstream — the breach happens at the moment the data flows.", C: "Anonymizing after the transfer concedes the transfer itself was of personal data and already non-compliant.", D: "An importer's domestic privacy policy is not an EU transfer mechanism and provides no legal basis for the flow." }, strat: "'FIRST' plus a border means: legal mechanism before movement. Any option that moves data first and papers it later is the trap.", trap: "wrong-economics", bok: "Domain II, Competency A" },
  { id: "e-ii-7", c: "ii-a", type: "recall", d: 2, stem: "US data broker Opalline builds AI propensity scores that insurers buy to screen applicants. Consumers discover they can neither view their Opalline profile nor correct the inaccurate inputs feeding their score. Which Fair Information Practice is most directly violated?", opts: [["Access and participation — individuals should be able to see the data held about them and contest or correct inaccuracies", true], ["Collection limitation — Opalline gathered more data than it needed", false], ["Security safeguards — the profiles are inadequately protected against breach", false], ["Purpose specification — the scores were put to a new, unstated purpose", false]], why: "The facts describe people shut out of seeing and correcting their own data — the access and participation principle. In an AI context it matters doubly, because uncorrectable upstream errors propagate into every downstream score.", wrong: { B: "Nothing in the facts concerns the volume collected; the complaint is about what consumers can see and fix.", C: "No security failure is described — the data is withheld from the subjects, not exposed to attackers.", D: "No repurposing is described; the scores are used for the screening purpose the broker built them for." }, strat: "FIP items are matching exercises: isolate the verb in the harm (cannot SEE, cannot CORRECT) and map it to the practice with the same verb.", trap: "none", bok: "Domain II, Competency A" },
  // ───────── II.B — other existing law applied to AI (7) ─────────
  { id: "e-ii-8", c: "ii-b", type: "distinction", d: 3, stem: "Lender Cordal Finance buys applicant risk files — including credit histories — from consumer reporting agency Veritract and feeds them into an AI underwriting model. The model declines Marisol's application. Under the FCRA, what does the decline specifically obligate Cordal to do?", opts: [["Provide an adverse-action notice tied to the consumer report, so Marisol learns of the report's role in the decision and can obtain and dispute the underlying information", true], ["Publish the model's feature weights so Marisol can audit the algorithm directly", false], ["Nothing — FCRA duties sit with Veritract as the consumer reporting agency, not with users of its reports", false], ["Retrain the model to remove credit history as an input before issuing further decisions", false]], why: "FCRA fires precisely when consumer-report data (such as credit history) drives an adverse decision: the user of the report owes disclosure through an adverse-action notice, opening the consumer's statutory path to obtain the report and dispute inaccurate information. The AI wrapper changes nothing about the mechanics.", wrong: { B: "FCRA mandates notice and dispute rights, not algorithmic transparency — model weights are nowhere in the statute's remedy.", C: "The too-narrow reading: report USERS carry their own duties, the adverse-action notice chief among them; CRA duties are additional, not substitutional.", D: "FCRA regulates the use of consumer reports — it does not ban credit data from lending, which is the statute's core sanctioned use." }, strat: "When an AI merely consumes consumer-report data, answer with the FCRA's own remedy chain: notice → access → dispute. Options about model internals are modern-sounding distractors.", trap: "too-narrow", bok: "Domain II, Competency B" },
  { id: "e-ii-9", c: "ii-b", type: "distinction", d: 3, stem: "Pharma start-up Nerevia claims its discovery model 'invented' a novel compound, and its design model generated the product's launch artwork with no human creative input. Counsel must brief the board on the US intellectual-property position. The accurate statement is:", opts: [["The patent application must name a human inventor — Thaler v. Vidal forecloses AI inventorship — and the purely AI-generated artwork lacks copyright protection absent human authorship, so commercial control of outputs rests on contract terms", true], ["The model can be named as inventor because Nerevia owns it, and the artwork is automatically copyrighted to Nerevia as the model's operator", false], ["Neither the compound nor the artwork can receive any IP protection, because AI was involved in both", false], ["Thaler v. Vidal held that all AI outputs fall into the public domain across both patent and copyright law", false]], why: "Thaler v. Vidal settled that US inventors must be natural persons, so an AI cannot be named inventor. Separately, copyright requires human authorship, so a work generated with no human creative input is unprotectable — which is why generative-AI output ownership must be allocated by contract.", wrong: { B: "Owning the tool does not make the tool an inventor, and operating a model is not the human authorship copyright requires.", C: "Too broad — AI-assisted inventions and works with genuine human creative contribution remain protectable; the bar falls only on purely machine-made claims.", D: "Synonym bait across regimes: Thaler v. Vidal is a patent-inventorship holding; it decided nothing about copyright." }, strat: "Keep the IP lanes separate: inventorship (patent, Thaler), authorship (copyright, human-authorship doctrine), and ownership-by-contract for outputs. Options that fuse the lanes are wrong.", trap: "synonym-bait", bok: "Domain II, Competency B" },
  { id: "e-ii-10", c: "ii-b", type: "best", d: 3, multi: true, stem: "General counsel at US employer Strydehall is inventorying which federal instruments impose enforceable legal duties relevant to its AI-driven hiring and screening stack. Which three belong on the binding list? Select THREE.", opts: [["The Fair Credit Reporting Act, where the tooling consumes consumer-report data such as credit histories", true], ["The Americans with Disabilities Act, as applied to screening tools that disadvantage candidates with disabilities", true], ["FTC Act Section 5, reaching unfair or deceptive practices in how the AI is used or described", true], ["The National AI Initiative Act of 2020, which sets duties for private-sector hiring algorithms", false], ["The White House Blueprint for an AI Bill of Rights, which binds employers deploying automated screening", false]], why: "FCRA, the ADA and FTC Act Section 5 are enforceable law that applies directly to AI-mediated hiring: consumer-report mechanics, disability discrimination, and unfair or deceptive practices respectively.", wrong: { D: "The NAIIA trap in new clothes: the 2020 Act creates a national R&D initiative and a coordination office — it imposes no duties on private-sector systems.", E: "The Blueprint (2022) is non-binding guidance; it signals policy direction but binds no employer." }, strat: "For 'binding' multi-selects, sort each instrument into statute-with-duties versus coordination/guidance. NAIIA and the Blueprint live permanently in the second pile.", trap: "true-but-irrelevant", bok: "Domain II, Competency B" },
  { id: "e-ii-11", c: "ii-b", type: "distinction", d: 3, stem: "After the EEOC resolves an enforcement action against another company's automated screener, Brynmor Foods' compliance team declares the agency's technical-assistance documents 'binding federal law' and freezes all AI hiring work until certified against them. The accurate characterization of EEOC guidance and enforcement actions is:", opts: [["They are not binding statutes, but they are strong evidence of the agency's enforcement view — prudent inputs to risk assessment under the law they interpret, such as the ADA and anti-discrimination statutes", true], ["They become binding on all US employers once the agency publishes them in any form", false], ["They are irrelevant to any company that was not a party to the enforcement action", false], ["They preempt state AI employment laws, so state-level compliance work can stop", false]], why: "EEOC guidance and case outcomes do not legislate: they bind no one beyond the parties, yet they are the clearest available signal of how the agency will enforce existing statutes against AI tools. Mature programs treat them as high-weight risk inputs — neither gospel nor noise.", wrong: { B: "The absolute pole: publication does not convert guidance into statute.", C: "The opposite absolute: non-parties ignore enforcement signals at their peril — the agency's theory of violation transfers to similar tools.", D: "Agency guidance cannot preempt state statutes; state AI employment laws operate on their own force." }, strat: "Status-of-instrument questions hide two mirrored absolutes ('binds everyone' / 'binds no one, ignore it'). The credited answer is the calibrated middle: not binding, strongly evidentiary.", trap: "absolute", bok: "Domain II, Competency B" },
  { id: "e-ii-12", c: "ii-b", type: "not", d: 3, stem: "Generative-media vendor Calliqo wants to shrink its US copyright-infringement exposure ahead of a funding round. Which measure contributes LEAST to that goal?", opts: [["Licensing the highest-risk portions of its training corpus from rights holders", false], ["Analyzing whether the remaining unlicensed training inputs qualify as fair use", false], ["Filtering outputs that closely reproduce identifiable works from the training set", false], ["Registering Calliqo's own model weights and interface code with the Copyright Office", true]], why: "Registration protects Calliqo's OWN works against copyists; it does nothing about Calliqo infringing other people's rights, which is where the exposure lives. Infringement risk is managed on the input side (licensing, fair-use analysis) and the output side (similarity filtering).", wrong: { A: "Licensing directly extinguishes claims for the covered works — a core mitigation.", B: "Ensuring training inputs qualify as fair use is the recognized input-side mitigation for training-data exposure.", C: "Output similarity is where infringement crystallizes in practice; filtering near-copies attacks the claim at its strongest point." }, strat: "LEAST items plant a genuinely useful action aimed at the wrong target. Ask whose rights each measure protects: three protect others' rights against Calliqo's use; one protects Calliqo's rights.", trap: "true-but-irrelevant", bok: "Domain II, Competency B" },
  { id: "e-ii-13", c: "ii-b", type: "best", d: 2, stem: "US software firm Ardenline markets its meeting-notes assistant as 'fully bias-free, 99.9% accurate AI' while internal testing shows materially worse performance. No statute names 'AI washing'. The most direct federal exposure is:", opts: [["FTC Act Section 5 — deceptive acts or practices, which reaches false or unsubstantiated AI capability claims", true], ["The National AI Initiative Act, which polices overstated AI research claims", false], ["The Take It Down Act, which covers deceptive AI marketing", false], ["None — capability puffery about software is federally unregulated", false]], why: "Section 5's prohibition on deceptive acts or practices applies to AI exactly as to any product: material claims a company cannot substantiate — 'bias-free', '99.9% accurate' — are classic deception territory for the FTC.", wrong: { B: "Real law, wrong purpose: NAIIA coordinates federal R&D and polices nothing in the private market.", C: "Real law, wrong subject: the Take It Down Act targets non-consensual intimate imagery and platform removal duties, not marketing claims.", D: "Specific, falsifiable performance claims are not puffery, and Section 5 squarely reaches them." }, strat: "'No statute names X' is a hint, not a shield — map novel conduct to the general-purpose statute (Section 5) rather than to AI-named laws with different subjects.", trap: "true-but-irrelevant", bok: "Domain II, Competency B" },
  { id: "e-ii-14", c: "ii-b", type: "best", d: 3, stem: "Tenant-screening SaaS Keystone Vetting scores rental applicants for US landlords using eviction-filing history and neighborhood-mobility features. An audit shows the scores disproportionately reject applicants from protected classes, though no protected attribute is an input and no one intended to discriminate. The clearest legal exposure is:", opts: [["Fair Housing Act liability on a disparate-impact theory — facially neutral screening that disproportionately excludes protected groups can violate housing-discrimination law without intent", true], ["No exposure, because the model never ingests protected attributes", false], ["Liability only if plaintiffs prove Keystone specifically intended to discriminate", false], ["Trade-secret misappropriation of competing scoring methods", false]], why: "Housing-discrimination law reaches algorithmic tenant screening, and disparate impact does not require intent: neutral features correlated with protected class — eviction filings, mobility patterns — can produce actionable exclusion all the same.", wrong: { B: "The input-blindness fallacy: omitting the protected attribute does nothing when proxy features carry the same signal.", C: "That describes disparate treatment; the disparate-impact theory exists precisely for unintended, pattern-level exclusion.", D: "An IP distractor with no connection to the discriminatory-outcome facts." }, strat: "'We don't collect race' is never the end of a discrimination analysis — hunt the proxies and apply impact, not intent.", trap: "too-narrow", bok: "Domain II, Competency B" },
  // ───────── II.C — AI-specific laws (15) ─────────
  { id: "e-ii-15", c: "ii-c", type: "distinction", d: 3, stem: "Bellvane Systems will place two Annex III high-risk systems on the EU market: Shortlist, a recruitment-screening tool (the employment area), and GateSight, a biometric identification product (Annex III point 1). The compliance head budgets for both to queue at a notified body. Which statement about the Article 43 conformity-assessment routes is accurate?", opts: [["Shortlist follows internal control under Annex VI with no third party, while GateSight may choose Annex VI only if it fully applies harmonised standards — where standards are absent or restricted, the Annex VII notified-body route is mandatory", true], ["Both require a notified body, because every Annex III system needs third-party certification", false], ["Both qualify for internal control, because self-assessment is the universal default across Annex III", false], ["GateSight needs no conformity assessment, because biometric identification is a prohibited practice", false]], why: "Article 43 splits Annex III: systems in points 2 through 8 (employment included) self-assess under the Annex VI internal-control procedure. Biometrics under point 1 is the conditional lane — the provider may choose Annex VI or Annex VII where it has fully applied harmonised standards, but Annex VII (notified body) becomes mandatory where those standards do not exist or were applied only in part.", wrong: { B: "Overstated — most Annex III providers never see a notified body; and as of early 2026 no AI-Act notified bodies had even been designated, so 'both must queue' doubly fails.", C: "The mirror absolute: point 1 biometrics breaks the 'universal' self-assessment claim whenever harmonised standards are unavailable.", D: "Biometric identification here is high-risk, not banned — Article 5 prohibits specific practices such as real-time remote biometric identification in public spaces for law enforcement, not the product category." }, strat: "Route questions turn on WHICH Annex III point you are in: point 1 is the only conditional third-party lane; points 2–8 self-assess under Annex VI.", trap: "absolute", bok: "Domain II, Competency C" },
  { id: "e-ii-16", c: "ii-c", type: "best", d: 3, stem: "Agrivolt builds an AI module that autonomously modulates emergency braking inside its EU-regulated harvester line — a safety component of machinery already subject to third-party conformity assessment under its sectoral product legislation, putting it in Annex I. For AI Act conformity, Agrivolt should expect:", opts: [["The AI Act requirements to be checked within the existing sectoral conformity procedure for the machinery, following that product legislation's route rather than a separate stand-alone AI assessment", true], ["A separate Annex VI self-assessment run independently of, and in parallel with, the machinery procedure", false], ["An Annex VII assessment by an AI-only notified body selected regardless of the machinery framework", false], ["No conformity assessment, because braking software of this kind predates the AI Act", false]], why: "Annex I products keep their sectoral conformity route: the AI Act's requirements for the high-risk AI safety component are folded into the conformity procedure the product legislation already mandates, avoiding duplicate assessments under two regimes.", wrong: { B: "Annex VI internal control is the stand-alone Annex III lane — importing it alongside the machinery procedure doubles the work the Act was designed to merge.", C: "The sectoral framework governs the route and the body; a free-standing AI-only assessment is not how Annex I works (and AI-Act notified-body designations were still pending in early 2026).", D: "Pre-existing software is not grandfathered out — Annex I embedded high-risk duties apply on their own timeline (from 2 August 2028 post-Omnibus)." }, strat: "Two high-risk lanes, two routes: Annex III stand-alone systems mostly self-assess; Annex I safety components ride their product law's existing procedure. Identify the lane before the route.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  { id: "e-ii-17", c: "ii-c", type: "best", d: 3, stem: "EU generative-music service Chantefleur has been on the market since March 2026. In September 2026 its counsel panics: machine-readable marking of the AI-generated audio is still not implemented, and Article 50 became applicable on 2 August 2026. The accurate advice is:", opts: [["Chantefleur can rely on the Omnibus marking grace until 2 December 2026 because it was on the market before 2 August 2026 — but its other Article 50 duties, such as disclosing to users that they are dealing with AI content, already apply", true], ["All Article 50 duties are deferred to 2 December 2027 together with the Annex III obligations", false], ["The grace period is unavailable, because it covers only systems launched after 2 August 2026", false], ["Marking duties never reach audio — the obligation covers only AI-generated images and video", false]], why: "The Digital Omnibus created a narrow marking grace: generative systems already on the market before 2 August 2026 have until 2 December 2026 to implement machine-readable marking. Everything else in Article 50 — including telling users they face AI content — applies from 2 August 2026, so Chantefleur's exposure is partial, not zero.", wrong: { B: "True of the high-risk timelines, irrelevant to Article 50 — the Omnibus moved Annex III to December 2027 and Annex I to August 2028, but transparency was pointedly NOT deferred.", C: "Scope inverted: the grace exists FOR legacy systems; anything launched after 2 August 2026 must mark from day one.", D: "An invented media carve-out — the labeling duty covers AI-generated content, not just pictures." }, strat: "The marking grace has two gates: generative system AND on the market before 2 August 2026. Check both gates and remember the grace covers the marking duty only, not Article 50 wholesale.", trap: "true-but-irrelevant", bok: "Domain II, Competency C" },
  { id: "e-ii-18", c: "ii-c", type: "role", d: 3, stem: "Lisbon start-up Ondamar takes an open-weight general-purpose model, fine-tunes it extensively on proprietary maritime data, and sells the result commercially as 'OndaCore' under its own name. Ondamar insists the GPAI-provider duties stay with the original lab because 'we only adapted someone else's model'. Under the EU AI Act's GPAI regime, Ondamar is best described as:", opts: [["A downstream modifier that can itself become the provider of the modified general-purpose model it places on the market, taking on the GPAI provider obligations for OndaCore", true], ["A deployer, because only training a model from scratch creates provider status", false], ["A distributor, because the underlying weights were created by another lab", false], ["Outside the AI Act entirely, because open-weight models carry no obligations downstream", false]], why: "A downstream actor that substantially modifies a GPAI model and places the result on the market under its own name can become that model's provider — the obligations travel with the act of providing, not with who ran the original pretraining.", wrong: { B: "Provider status has never required from-scratch training; marketing a modified model under your own name is the trigger.", C: "Distributors pass systems along WITHOUT modification — extensive fine-tuning and rebranding is the opposite of distribution.", D: "Open-source exemptions are partial and conditional (and fall away entirely for systemic-risk models); they do not immunize a commercial downstream release." }, strat: "Follow the Act's role logic: ask who places what on the market under whose name, not who wrote the first training run. 'We only adapted it' is the modern version of the rebranding trap.", trap: "too-narrow", bok: "Domain II, Competency C" },
  { id: "e-ii-19", c: "ii-c", type: "best", d: 3, stem: "Frontier lab Veltrix declines to sign the AI Office's GPAI Code of Practice, calling it voluntary box-ticking. Its policy team asks what the refusal actually changes. The accurate consequence is:", opts: [["Veltrix still owes every GPAI obligation and simply loses the presumption-of-conformity shortcut — it must demonstrate compliance through alternative adequate means, inviting closer regulatory scrutiny", true], ["Nothing changes — unsigned providers are exempt until harmonised standards are published", false], ["Refusing to sign is itself a violation, triggering the €15M or 3% GPAI penalty tier", false], ["Veltrix loses the right to operate in the EU until it signs", false]], why: "Adherence to the Code of Practice gives GPAI providers a presumption of conformity — it is the easy evidentiary road, not the obligation itself. Declining leaves the substantive GPAI duties (in force since 2 August 2025) fully intact; the provider must prove compliance some other adequate way and can expect more questions.", wrong: { B: "The exemption myth: the Code is a route to demonstrate compliance with duties that bind signatories and non-signatories alike.", C: "Penalties attach to breaching GPAI obligations, not to declining a voluntary code.", D: "No market ban flows from non-signature — the catastrophizing absolute." }, strat: "Separate the obligation from the evidence of meeting it. Voluntary instruments (Code of Practice, harmonised standards) buy presumptions; refusing them forfeits the shortcut, never the duty — and never creates one.", trap: "absolute", bok: "Domain II, Competency C" },
  { id: "e-ii-20", c: "ii-c", type: "distinction", d: 3, stem: "During a market-surveillance inquiry, Finnish scale-up Raukko — 80 staff, qualifying as an SME — supplies the authority with testing documentation it knows is incomplete and misleading about its high-risk system's accuracy. Which penalty analysis is correct?", opts: [["The conduct sits in the €7.5M or 1% tier for supplying incorrect, incomplete or misleading information to authorities — and as an SME, Raukko faces the LOWER of the fixed amount and the percentage, not the higher", true], ["It is a prohibited-practice violation, exposing Raukko to the €35M or 7% tier", false], ["It falls in the €15M or 3% tier, and every firm pays whichever of the two figures is higher", false], ["Misleading a regulator is left to national criminal law — the AI Act sets no fine for it", false]], why: "The Act prices this conduct specifically: supplying incorrect, incomplete or misleading information to notified bodies or authorities is the lowest tier, €7.5M or 1% of global turnover. The usual rule takes the HIGHER of the two figures, but for SMEs and start-ups proportionality flips it — they pay the lower.", wrong: { B: "The top tier is reserved for Article 5 prohibited practices; lying to a regulator is serious but sits in its own, lowest tier.", C: "Two errors: that is the mid tier for most substantive obligations, and the higher-of rule is exactly what the SME carve-out reverses.", D: "The Act expressly fines this conduct — no need to reach for national criminal law." }, strat: "Penalty items are two questions in one: which tier does the CONDUCT match, and which cap does the ACTOR pay. Check the SME flip before you accept any 'higher of' language.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  { id: "e-ii-21", c: "ii-c", type: "distinction", d: 3, stem: "Nivara AI trains a general-purpose model using 4×10^25 FLOPs of compute and will serve both EU customers and Californians. Counsel must state which compute-threshold regimes presumptively attach. The correct reading is:", opts: [["In the EU the model is presumed systemic-risk GPAI, because training compute exceeds 10^25 FLOPs; under California SB 53 it sits below the 10^26 frontier threshold, so the frontier-developer duties do not presumptively attach", true], ["It clears both thresholds, since 4×10^25 exceeds 10^25 and 10^26 alike", false], ["It clears neither threshold, because both regimes bite only above 10^26", false], ["Thresholds are beside the point — both regimes turn solely on downstream use context", false]], why: "The two regimes sit an order of magnitude apart: the EU presumes systemic risk above 10^25 FLOPs of training compute, while California SB 53 defines frontier developers above 10^26 operations. 4×10^25 is above the first line and below the second.", wrong: { B: "The exponent slip the item exists to catch: 4×10^25 is 0.4×10^26 — short of California's line.", C: "The EU presumption sits at 10^25, which this run exceeds fourfold.", D: "Context drives risk classification elsewhere, but both of these specific regimes use compute thresholds to trigger their heightened tier." }, strat: "Write the two numbers down before judging any scenario: EU systemic-risk GPAI 10^25, SB 53 frontier 10^26. Then do the arithmetic — IAPP counts on you pattern-matching the mantissa and ignoring the exponent.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  { id: "e-ii-22", c: "ii-c", type: "recall", d: 3, stem: "A safety engineer at Halcyard, a frontier developer covered by California SB 53, confirms a critical safety incident. In the war room someone insists the report is due in '48 hours — it's federal law'. Under SB 53, the correct reporting discipline to the California Office of Emergency Services is:", opts: [["15 days for a critical safety incident, compressed to 24 hours where there is imminent risk of death or serious physical injury — the 48-hour clock belongs to the federal Take It Down Act's NCII removals, not SB 53", true], ["48 hours for all incidents, mirroring the federal takedown statute", false], ["30 days, aligned with general data-breach notification norms", false], ["No fixed deadline — SB 53 requires only an annual published transparency report", false]], why: "SB 53 gives frontier developers 15 days to report a critical safety incident to Cal OES, collapsing to 24 hours when the incident poses imminent risk of death or serious injury. The 48-hour figure is a different statute entirely — the Take It Down Act's platform window for removing non-consensual intimate imagery.", wrong: { B: "The planted number swap: 48 hours is the Take It Down Act's notice-and-removal window — different law, different subject matter.", C: "An invented alignment; SB 53 wrote its own clocks.", D: "SB 53 pairs its published safety-framework duty with incident reporting on fixed deadlines — the annual-report framing erases the sharper obligation." }, strat: "Build a deadline table and attribute every clock to its statute: 48h Take It Down, 15d/24h SB 53 Cal OES. Deadline questions are won before exam day.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  { id: "e-ii-23", c: "ii-c", type: "distinction", d: 3, stem: "Seoul fintech Hanbit Credit runs a loan-evaluation AI domestically and is expanding to the EU, where the system will qualify as Annex III high-risk. The board asks how the two regimes differ for market entry. The accurate contrast is:", opts: [["Korea requires Hanbit to assess in advance whether the system is high-impact and meet operator duties, with no mandatory third-party conformity assessment and administrative fines up to ₩30 million; the EU requires a pre-market conformity assessment, with penalties scaling to €35M or 7% at the top tier", true], ["Both jurisdictions require notified-body certification before launch", false], ["Korea's fines mirror the EU's €35M ceiling to deter global players", false], ["The EU relies on operators self-assessing high-impact status, while Korea mandates CE-style certification", false]], why: "The AI Basic Act is innovation-first: the operator itself assesses in advance whether its system is high-impact, then meets duties like meaningful explanation and human oversight — with no mandatory third-party conformity assessment and fines capped at ₩30 million (roughly US$20k). The EU runs the opposite architecture: conformity assessment before market, penalties reaching €35M or 7%.", wrong: { B: "Korea has no notified-body requirement at all — and even in the EU most Annex III systems self-assess under Annex VI.", C: "The number swap: ₩30 million is three orders of magnitude below the EU ceiling, a deliberate design difference, not a rounding error.", D: "The regimes inverted, vocabulary included — 'high-impact' and advance self-assessment are Korea's; conformity assessment and CE marking are the EU's." }, strat: "Anchor each regime to one word: EU 'high-risk' plus conformity assessment; Korea 'high-impact' plus advance self-assessment. Any option that crosses the vocabulary has crossed the regimes.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  { id: "e-ii-24", c: "ii-c", type: "role", d: 3, stem: "The public employment agency of an EU member state will deploy Mettle, a third-party Annex III system that scores jobseekers for program eligibility. The governance office asks who owes the fundamental rights impact assessment and how it relates to the GDPR assessment already underway. The correct allocation is:", opts: [["The agency, as a public-body deployer, owes the FRIA before first use — and, as controller, the DPIA under the GDPR; the two are related exercises it can align, since both demand identified risks plus mitigation measures", true], ["Mettle's provider owes the FRIA, because impact assessments follow whoever built the system", false], ["The FRIA replaces the DPIA, so running both would be duplicative error", false], ["Neither assessment applies — FRIAs attach only to private credit-scoring and insurance deployers", false]], why: "The FRIA is a deployer duty aimed at public bodies and public-service providers (extended to private deployers of credit-scoring and life/health-insurance systems), due before first use. The DPIA is the controller's GDPR duty. A public agency deploying the system typically wears both hats, and the assessments share a skeleton — risks identified, mitigations planned — so they can be sequenced and aligned rather than duplicated from scratch.", wrong: { B: "The role flip: the provider runs the conformity assessment; the FRIA was placed deliberately on the deployer, who knows the context of use.", C: "They coexist with different lenses — fundamental rights versus personal-data risks; neither displaces the other.", D: "Public bodies are the FRIA's core addressees; the credit and insurance clause EXTENDS coverage to certain private deployers, it does not define the whole duty." }, strat: "Pin each assessment to its owner before touching the options: FRIA = deployer (public bodies plus private credit/insurance), DPIA = controller. Then look for the option that keeps both alive and aligned.", trap: "too-narrow", bok: "Domain II, Competency C" },
  { id: "e-ii-25", c: "ii-c", type: "best", d: 3, stem: "Dallane Mortgage deploys the same automated underwriting assistant in Texas and Colorado. A 2027 audit finds unintended disparate outcomes for a protected group; Dallane never intended discrimination, and the tool materially influences loan decisions. The sharpest reading of its state-law posture is:", opts: [["TRAIGA exposure is limited because that statute targets intentional prohibited uses, but Colorado SB 26-189's ADMT duties — disclosure, adverse-outcome explanation, correction rights and human review — attach from 1 January 2027 regardless of intent", true], ["Both statutes impose identical strict liability for any disparate outcome, so the state analysis is uniform", false], ["SB 26-189 is inapplicable because the tool merely assists human underwriters rather than deciding alone", false], ["TRAIGA governs only Texas government agencies, so a private deployer sits wholly outside it", false]], why: "The two statutes split on intent: Texas's TRAIGA (effective 1 January 2026) is intent-based, attaching liability to intentional prohibited uses, while Colorado's SB 26-189 (effective 1 January 2027) is impact- and transparency-based — its consumer duties fire whenever automated decision technology materially influences a consequential decision, with no intent element. Same tool, same facts, different exposure.", wrong: { B: "Neither statute is strict liability, and flattening them erases the exact intent-versus-impact line the item tests.", C: "Materially influencing the consequential decision IS the SB 26-189 trigger — a human presence downstream does not negate material influence.", D: "TRAIGA also governs government use, but its prohibited-use bans reach private actors; 'wholly outside' overshoots." }, strat: "For multistate questions, tag each statute with its trigger: TRAIGA = intent, SB 189 = material influence on a consequential decision. Unintended disparate impact then sorts itself.", trap: "too-narrow", bok: "Domain II, Competency C" },
  { id: "e-ii-26", c: "ii-c", type: "distinction", d: 3, stem: "Voice-authentication vendor Clarivox enrolled Illinois gym members' voiceprints without written consent, and runs the same product in Texas and Colorado. Plaintiffs' firms are circling Illinois while barely glancing at the other states. Why does Illinois dominate the litigation forecast?", opts: [["BIPA grants individuals a private right of action with statutory damages, while TRAIGA and Colorado SB 26-189 route enforcement exclusively through the attorney general — so only Illinois lets the gym members sue Clarivox directly", true], ["Illinois damages have been uncapped per scan since the 2024 amendment", false], ["Texas and Colorado impose no obligations on biometric AI at all", false], ["BIPA is enforced by the FTC, the most aggressive available regulator", false]], why: "BIPA's distinctive feature is the private right of action: individuals whose biometric identifiers were collected without the required written consent can sue for statutory damages themselves. The newer AI statutes went the other way — TRAIGA and SB 26-189 are AG-enforced with no private right — which is exactly why the plaintiffs' bar concentrates on Illinois.", wrong: { B: "Direction flipped: the 2024 amendment LIMITED per-scan damages accrual, reining the exposure in rather than uncapping it.", C: "The absolute overshoots — both states regulate; they simply lodge enforcement with the attorney general instead of private plaintiffs.", D: "BIPA is an Illinois state statute vindicated through private suits; the FTC has no role in it." }, strat: "For any US AI statute, file one fact first: who gets to sue. Private right of action (BIPA) versus AG-only (TRAIGA, SB 189) predicts where the litigation goes before you read another word.", trap: "absolute", bok: "Domain II, Competency C" },
  { id: "e-ii-27", c: "ii-c", type: "best", d: 3, stem: "Garnet & Pike, a law firm hiring for its Manhattan office, buys an AI tool that automatically ranks and filters applicants before any human review. HR assumes that because the firm is small and the tool came from a vendor, no New York City obligations arise. Under Local Law 144, the firm must:", opts: [["Ensure the automated employment decision tool has undergone an independent bias audit and give candidates the required notice before using it to screen them", true], ["Register the tool with the FTC and file its training data for review", false], ["Do nothing — LL144 obligations fall solely on the tool's vendor", false], ["Stop using the tool, because AEDTs are banned in New York City", false]], why: "Local Law 144 conditions the USE of automated employment decision tools: an independent bias audit and candidate notice are the price of screening NYC candidates with an AEDT, and the law has been enforced since July 2023. Buying the tool from a vendor does not move the compliance posture off the employer using it.", wrong: { B: "Wrong regulator and invented mechanics — a New York City local law involves no FTC registration or training-data filing.", C: "The outsourcing trap: the employer deploying the AEDT owes the audit-and-notice posture; procurement does not transfer it away.", D: "LL144 regulates AEDTs, it does not prohibit them — audit plus notice, not a ban." }, strat: "City and state AI laws usually attach to the USER of the tool in the jurisdiction. 'The vendor handles compliance' is a recurring wrong answer across LL144, Colorado and EU deployer items alike.", trap: "too-narrow", bok: "Domain II, Competency C" },
  { id: "e-ii-28", c: "ii-c", type: "ordering", d: 3, stem: "Vespry Analytics is readying its Annex III claims-triage system for the EU market via the internal-control route, and lists its provider duties: (1) complete the Annex VI conformity assessment; (2) draw up the EU declaration of conformity and affix CE marking; (3) establish the risk-management system, quality management system and technical documentation; (4) run post-market monitoring and serious-incident reporting; (5) register the system in the EU database and place it on the market. Which sequence is correct?", opts: [["3 → 1 → 2 → 5 → 4", true], ["1 → 3 → 2 → 5 → 4", false], ["3 → 2 → 1 → 5 → 4", false], ["5 → 3 → 1 → 2 → 4", false]], why: "Build the compliance substance first — risk management, QMS, technical documentation — because that is what the conformity assessment evaluates. Assessment done, the provider declares conformity and affixes the CE mark, then registers in the EU database and places the system on the market, after which post-market monitoring and incident reporting run for the system's life.", wrong: { B: "Assessing conformity before the risk-management system, QMS and documentation exist means assessing nothing — the inputs to Annex VI are missing.", C: "Declaring conformity and CE-marking before the assessment attests to a review that has not happened; the mark certifies a COMPLETED procedure.", D: "Placing on the market first is the cart before every horse — market access is what the whole sequence unlocks, and registration precedes it." }, strat: "Compliance orderings follow one rule: substance → assessment → attestation → market → monitoring. Any sequence that markets early or attests before assessing is out.", trap: "premature", bok: "Domain II, Competency C" },
  { id: "e-ii-29", c: "ii-c", type: "ordering", d: 3, stem: "A compliance curriculum asks trainees to order when these EU AI Act obligation blocks became or become applicable, as the timeline stands after the Digital Omnibus: (1) GPAI model obligations and the governance regime; (2) prohibitions and AI-literacy duties; (3) Article 50 transparency duties; (4) Annex III stand-alone high-risk obligations; (5) Annex I embedded high-risk obligations. The correct chronological order is:", opts: [["2 → 1 → 3 → 4 → 5", true], ["1 → 2 → 3 → 4 → 5", false], ["2 → 1 → 4 → 3 → 5", false], ["2 → 3 → 1 → 5 → 4", false]], why: "Post-Omnibus the ladder runs: prohibitions and AI literacy on 2 February 2025; GPAI obligations and governance on 2 August 2025; Article 50 transparency on 2 August 2026 (not deferred); Annex III stand-alone high-risk on 2 December 2027; Annex I embedded high-risk on 2 August 2028.", wrong: { B: "Prohibitions and literacy led the whole regime on 2 February 2025 — six months before the GPAI block.", C: "The deferral myth: the Omnibus moved the high-risk dates but left Article 50 at 2 August 2026, more than a year BEFORE Annex III bites.", D: "GPAI preceded transparency by a year, and Annex III (December 2027) comes before Annex I (August 2028), not after." }, strat: "Memorize the ladder as a chant — prohibitions, GPAI, transparency, Annex III, Annex I — then hang the dates on it. Wrong sequences almost always smuggle in 'transparency was deferred'.", trap: "synonym-bait", bok: "Domain II, Competency C" },
  // ───────── II.D — standards & frameworks (7) ─────────
  { id: "e-ii-30", c: "ii-d", type: "best", d: 3, stem: "Insurer Bravalta maps the context of every AI use case, tracks fairness and drift metrics on live dashboards, and runs playbooks that prioritize and act on flagged risks. Yet audits keep surfacing orphaned models: no named risk owners, no policies, no escalation path, and inconsistent decisions across teams. In NIST AI RMF terms, the root deficiency is:", opts: [["GOVERN — the cross-cutting function that establishes culture, policies, roles and accountability and informs MAP, MEASURE and MANAGE; without it the other three run as disconnected activities", true], ["MAP — the firm has failed to identify the context its systems operate in", false], ["MEASURE — the metrics program needs more statistical rigor", false], ["MANAGE — the playbooks simply need to execute more frequently", false]], why: "Bravalta is performing MAP (context), MEASURE (tracking) and MANAGE (prioritized action) — what is missing is the function that makes them one system. GOVERN cultivates the risk-management culture and supplies the policies, roles and accountability that inform the other three; its absence is exactly what orphaned models and inconsistent decisions look like.", wrong: { B: "Context mapping is described as working — the gap is ownership, not understanding of use.", C: "Measurement exists and runs; sharpening statistics cannot conjure accountability.", D: "Faster playbooks without named owners and escalation paths just makes the disconnection run more often." }, strat: "Diagnose RMF scenarios by what is PRESENT, then name the absent function. Symptoms in the accountability register — no owners, no policy, no escalation — always point to GOVERN.", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },
  { id: "e-ii-31", c: "ii-d", type: "distinction", d: 3, stem: "A US agency CTO asks for two specific NIST resources: (1) the program for assessing the risks and impacts of AI models, built around an AI risk assessment framework; and (2) the resource that layers generative-AI-specific risks onto the core risk framework. The correct pairing is:", opts: [["(1) ARIA — Assessing Risks and Impacts of AI; (2) the Generative AI Profile, NIST AI 600-1", true], ["(1) the AI RMF Playbook; (2) ISO/IEC 42005", false], ["(1) the Generative AI Profile; (2) ARIA", false], ["(1) ARIA; (2) the OECD AI Principles", false]], why: "ARIA is NIST's program for Assessing Risks and Impacts of AI, with an AI risk assessment framework as its central component. The Generative AI Profile (AI 600-1) is the companion that layers GenAI-specific risks onto the AI RMF.", wrong: { B: "The Playbook operationalizes the RMF's four functions, and 42005 is an ISO impact-assessment standard — neither matches the asks.", C: "The two swapped — a pure name-recognition trap for anyone who memorized the acronyms without their jobs.", D: "The OECD Principles are international values-based principles, not a NIST profile for generative AI." }, strat: "Learn NIST artifacts as name-plus-job pairs (ARIA assesses risks and impacts; AI 600-1 profiles GenAI onto the RMF). Swap-the-labels options collapse instantly.", trap: "synonym-bait", bok: "Domain II, Competency D" },
  { id: "e-ii-32", c: "ii-d", type: "best", d: 3, multi: true, stem: "A governance lead is briefing the board ahead of an ISO/IEC 42001 certification push and tests her own claims about the ISO/IEC AI landscape. Which three statements are accurate? Select THREE.", opts: [["ISO/IEC 42001 defines a certifiable AI management system — the AI analogue of certifying against ISO/IEC 27001", true], ["ISO/IEC 42005 guides AI system impact assessment and is a companion to the management system, not a certification target", true], ["ISO/IEC 22989 supplies the shared AI concepts and terminology the other standards build on", true], ["ISO/IEC 23894 is the certifiable AI security standard that replaces 42001 for high-risk systems", false], ["ISO/IEC 42001 certification is legally mandatory for providers under the EU AI Act", false]], why: "42001 is the certifiable AI management-system standard; 42005 is impact-assessment guidance that complements it rather than competing with it; and 22989 is the vocabulary layer — concepts and terminology — underneath the suite.", wrong: { D: "23894 is AI risk-management guidance — not a security standard, not certifiable, and nothing in the suite 'replaces' 42001.", E: "The AI Act never mandates ISO certification; conformity runs through the Act's own assessment routes, with harmonised standards supplying presumptions." }, strat: "For ISO multi-selects, attach one noun to each number — 42001 management system (certifiable), 42005 impact assessment, 22989 vocabulary, 23894 risk guidance — and reject any option that upgrades guidance into certification or standards into legal mandates.", trap: "synonym-bait", bok: "Domain II, Competency D" },
  { id: "e-ii-33", c: "ii-d", type: "recall", d: 2, stem: "An EU high-risk-system provider wants its quality management system to carry a presumption of conformity with the AI Act's QMS requirement by following a harmonised European standard published in 2026. The relevant standard is:", opts: [["EN 18286 — the harmonised quality-management-system standard developed to support the AI Act", true], ["ISO/IEC 22989 — the AI vocabulary standard", false], ["NIST AI 600-1 — the Generative AI Profile", false], ["ISO 9001 — the generic quality standard, which automatically confers AI Act conformity", false]], why: "EN 18286 (2026) is the harmonised European QMS standard supporting the AI Act — and following a harmonised standard is what earns the presumption of conformity for the requirements it covers.", wrong: { B: "22989 defines concepts and terminology; it contains no quality management system.", C: "A US framework profile with no EU harmonisation status — it can inform practice but confers no presumption.", D: "Generic quality certification is not an AI-Act harmonised standard, and 'automatically confers' is the giveaway overclaim." }, strat: "Presumption of conformity flows only from harmonised standards cited for the specific requirement — match the standard to BOTH the requirement (QMS) and the regime (EU harmonised).", trap: "synonym-bait", bok: "Domain II, Competency D" },
  { id: "e-ii-34", c: "ii-d", type: "not", d: 3, stem: "Maristella Bank is evaluating an open-weight model whose publisher has documented ties to coordinated disinformation operations and a record of shipping untested releases. Reviewers score the vendor diligence against the OECD AI Principles. Which principle is LEAST implicated by this review?", opts: [["Robustness, security and safety", false], ["Accountability", false], ["Inclusive growth, sustainable development and well-being", true], ["Transparency and explainability", false]], why: "The live concerns with a bad-actor publisher are concrete: will the model hold up (robustness, security and safety), who answers for harm (accountability), and can its provenance and behavior be understood (transparency). The aspirational growth-and-well-being principle is the one this diligence exercise barely touches — the recurring IAPP pattern for risky-vendor scenarios.", wrong: { A: "Untested releases put robustness, security and safety at the center of the review.", B: "A publisher with a documented misuse record raises exactly the who-answers-for-this question.", D: "Disinformation ties make provenance, transparency and explainability primary screening criteria." }, strat: "In risky-vendor OECD items, the LEAST-relevant slot is reliably the aspirational principle (inclusive growth, sustainable development, well-being); the security-shaped facts light up the other four.", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },
  { id: "e-ii-35", c: "ii-d", type: "best", d: 3, multi: true, stem: "A vendor sells parole boards an AI that recommends release decisions. It offers the reviewing judges no account of how recommendations are produced, gives staff no way to decline or override the system's conclusion, and when recommendations later prove wrong the vendor cannot establish why. The training data was lawfully licensed with documented consent. Which three Asilomar AI Principles does this arrangement most directly violate? Select THREE.", opts: [["Judicial transparency — autonomous involvement in judicial decision-making should carry an explanation auditable by a competent human authority", true], ["Human control — people should retain the choice of whether and how to delegate decisions to AI systems", true], ["Failure transparency — when an AI system causes harm, it should be possible to ascertain why", true], ["Personal privacy — the system misuses individuals' data", false], ["Shared benefit — the technology's gains are being hoarded by a single firm", false]], why: "Each failure maps to a named ethics-bucket principle: no auditable explanation for the judges (judicial transparency), no ability to decline or override (human control), and unexplainable failures after harm (failure transparency).", wrong: { D: "The planted miss: the stem stipulates lawfully licensed, consented data — privacy is the principle the facts deliberately take OFF the table.", E: "Benefit distribution is not in play; nothing in the facts concerns who shares the technology's gains." }, strat: "Asilomar cluster items reward literal mapping: match each fact to the principle whose name describes it, and respect stipulations ('lawfully licensed with consent') that eliminate a tempting option.", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },
  { id: "e-ii-36", c: "ii-d", type: "distinction", d: 3, stem: "After an adverse credit decision, a regulator demands the record of what the system did and when, while the declined applicant demands to understand how the decision about her was reached. A junior analyst files both as 'the same transparency request'. Under NIST AI RMF's trustworthy-AI characteristics, the correct framing is:", opts: [["They differ: transparency answers 'what happened' — information about the system and its outputs — while explainability answers 'how the decision was made'; the characteristics are distinct and mutually supporting", true], ["They are synonyms that NIST merged into a single characteristic", false], ["Transparency is satisfied only by open-sourcing the model's code", false], ["Explainability is owed to regulators, while transparency is owed only to consumers", false]], why: "NIST keeps the two apart: transparency covers what happened — the availability of information about the system and its outputs — while explainability covers how a decision was made. The regulator's request is a transparency ask; the applicant's is an explainability ask. Distinct, and mutually supporting.", wrong: { B: "The synonym bait itself — NIST lists them within distinct characteristics precisely because they answer different questions.", C: "Too narrow: transparency is about information availability, not a code-release mandate.", D: "An invented audience split — both characteristics serve regulators, users and affected people alike." }, strat: "When two near-neighbor terms appear in one stem, the question IS the distinction. Anchor on NIST's phrasing: transparency 'what happened', explainability 'how decided'.", trap: "synonym-bait", bok: "Domain II, Competency D" },
];

export const examPoolII: Question[] = raw.map((r) => ({
  id: r.id,
  competencyId: r.c,
  type: r.type,
  difficulty: r.d,
  stem: r.stem,
  isMultiselect: r.multi ?? false,
  options: r.opts.map(([text, isCorrect], i) => o(String.fromCharCode(65 + i), text, isCorrect, i)),
  correctExplanation: r.why,
  whyWrong: r.wrong ?? {},
  strategyNote: r.strat,
  trapType: r.trap ?? "none",
  bokRef: r.bok,
  source: "curated",
}));
